import { isMissingTileError } from "./util/tile-utils.js";
import { TaskQueue, taskKey } from "./util/task-queue.js";
import { scoreTask, } from "./util/task-scorer.js";
import { GeoTIFFRegistry } from "./util/geotiff-registry.js";
/**
 * Background tile-prefetch pipeline for nearby frames.
 *
 * On every `TimeCOGLayer.updateState`, the prefetcher receives the
 * current visible tile coordinates, the frame schedule window, the
 * interaction mode, and the quality policy. For each scheduled frame
 * (excluding the target, already loaded by the sublayer), it creates
 * `(frameId, x, y, z)` tasks and scores them by temporal distance,
 * playback direction, buffer need, and telemetry-based estimates.
 *
 * ## Scoring
 *
 * Tasks are scored via {@link scoreTask} with seven additive factors:
 * temporal proximity, directional playback boost, buffer shortfall
 * pressure, interaction-mode override, quality-urgency (preview
 * upgrade / fresh-preview bonus), log₂ size-hint penalty, and
 * ETA-based latency penalty. The final score is clamped to `[0, 200]`.
 *
 * ## Adaptive concurrency
 *
 * When abort rate exceeds 50%, max concurrency is halved to reduce
 * wasted work. When abort rate stays below 10% for 3+ consecutive
 * update cycles, concurrency is gradually restored.
 */
export class FramePrefetcher {
    tileCache;
    taskQueue = new TaskQueue();
    device = null;
    getTileData = null;
    pool = null;
    layerSignal;
    uploadsThisFrame = 0;
    maxConcurrent;
    maxDecodeTasks;
    maxGpuUploads;
    originalMaxConcurrent;
    consecutiveLowAbort = 0;
    rttEWMA = 0;
    throughputEWMA = 0;
    totalTasks = 0;
    abortedTasks = 0;
    /** Per-frame EWMA of tile byteLength, used for ETA-aware size penalty. */
    frameAvgBytes = new Map();
    defaultScoringWeights;
    internalRegistry = new GeoTIFFRegistry(8);
    sharedRegistry = null;
    /**
     * Tile keys known to not exist in their source COG (out-of-bounds
     * coordinates). Prevents the prefetcher from infinitely
     * re-requesting tiles that `decodeGeoTIFFTile` returns `null` for.
     */
    missingTileKeys = new Set();
    constructor(tileCache, maxConcurrent = 4, maxDecodeTasks, maxGpuUploads, scoringWeights) {
        this.tileCache = tileCache;
        this.maxConcurrent = maxConcurrent;
        this.originalMaxConcurrent = maxConcurrent;
        this.maxDecodeTasks = maxDecodeTasks ?? maxConcurrent;
        this.maxGpuUploads = maxGpuUploads ?? Math.max(1, Math.floor(maxConcurrent / 2));
        this.defaultScoringWeights = scoringWeights ?? {};
    }
    /** @internal Public for test compatibility. */
    get queue() {
        return this.taskQueue.queue;
    }
    /** @internal Public for test compatibility. */
    get inFlight() {
        return this.taskQueue.inFlight;
    }
    /** @internal Public for test compatibility. */
    get queuedKeys() {
        return this.taskQueue.queuedKeys;
    }
    /** @internal Exposed for test pre-population (`prefetcher.geotiffs.set(...)`). */
    get geotiffs() {
        return (this.sharedRegistry ?? this.internalRegistry).mutableMap;
    }
    /** @internal Exposed for test verification of the negative tile cache. */
    get missingKeys() {
        return this.missingTileKeys;
    }
    /** @internal Public for test assertions on adaptive concurrency. */
    get currentMaxConcurrent() {
        return this.maxConcurrent;
    }
    update(snapshot) {
        this.device = snapshot.device;
        this.getTileData = snapshot.getUserTileData;
        this.pool = snapshot.pool;
        this.layerSignal = snapshot.signal;
        this.uploadsThisFrame = 0;
        this.sharedRegistry = snapshot.geotiffRegistry ?? null;
        const scheduledIds = new Set(snapshot.scheduledFrames.map((f) => f.id));
        this.taskQueue.abortStale(scheduledIds);
        this.taskQueue.prune(scheduledIds, this.tileCache);
        const newTasks = [];
        const interactionMode = snapshot.interactionMode;
        const coverage = snapshot.coverage ?? 1;
        const abortRate = this.abortedTasks / (this.totalTasks || 1);
        this.maxConcurrent = this.computeConcurrency(abortRate);
        const skipFutureFrames = coverage < 0.5 && interactionMode !== "idle";
        const scoringCtx = {
            getTileCache: () => this.tileCache,
            getRttEWMA: () => this.rttEWMA,
            getThroughputEWMA: () => this.throughputEWMA,
            getFrameAvgBytes: (frameId) => this.frameAvgBytes.get(frameId) ?? 0,
            playing: snapshot.playing,
            playbackRate: snapshot.playbackRate,
            interactionMode: snapshot.interactionMode,
            coverage,
            bufferState: snapshot.bufferState,
            scheduledFrames: snapshot.scheduledFrames,
            targetFrame: snapshot.targetFrame,
        };
        for (const frame of snapshot.scheduledFrames) {
            if (frame.id === snapshot.targetFrame.id) {
                continue;
            }
            const distanceIndex = snapshot.scheduledFrames.indexOf(frame) -
                snapshot.scheduledFrames.indexOf(snapshot.targetFrame);
            if (skipFutureFrames && distanceIndex !== 0) {
                continue;
            }
            for (const tile of snapshot.visibleTiles) {
                const key = taskKey(frame.id, tile.x, tile.y, tile.z);
                const existing = this.tileCache.peek(frame.id, tile.x, tile.y, tile.z);
                if (existing?.quality === "full") {
                    continue;
                }
                if (this.missingTileKeys.has(key)) {
                    continue;
                }
                if (this.taskQueue.isTracked(key)) {
                    continue;
                }
                const task = {
                    frameId: frame.id,
                    frameUrl: frame.url,
                    requestInit: frame.requestInit,
                    byteSizeHint: frame.byteSizeHint,
                    x: tile.x,
                    y: tile.y,
                    z: tile.z,
                    quality: "full",
                    priority: 0,
                };
                task.priority = scoreTask(task, distanceIndex, scoringCtx, { ...this.defaultScoringWeights, ...snapshot.scoringWeights });
                newTasks.push(task);
                this.taskQueue.markQueued(key);
            }
        }
        this.taskQueue.enqueue(newTasks);
        this.pump();
    }
    abortAll() {
        this.taskQueue.abortAll();
        this.missingTileKeys.clear();
    }
    destroy() {
        this.abortAll();
        this.internalRegistry.clear();
    }
    getInFlightKeys() {
        return this.taskQueue.getInFlightKeys();
    }
    /** @deprecated Abort rate is now tracked via {@link stats}.abortRate. */
    getAbortedKeys() {
        return new Set();
    }
    stats() {
        const denominator = this.totalTasks || 1;
        return {
            prefetchTaskCount: this.taskQueue.activeCount + this.taskQueue.queue.length,
            queuedTaskCount: this.taskQueue.queue.length,
            inFlightTaskCount: this.taskQueue.activeCount,
            rttEWMA: this.rttEWMA,
            throughputEWMA: this.throughputEWMA,
            abortRate: this.abortedTasks / denominator,
            totalAborted: this.abortedTasks,
        };
    }
    computeConcurrency(abortRate) {
        let effective = this.maxConcurrent;
        if (abortRate > 0.5 && this.totalTasks > 4) {
            effective = Math.max(1, Math.floor(this.originalMaxConcurrent / 2));
            this.consecutiveLowAbort = 0;
        }
        else if (abortRate < 0.1) {
            this.consecutiveLowAbort += 1;
            if (this.consecutiveLowAbort >= 3 &&
                this.maxConcurrent < this.originalMaxConcurrent) {
                effective = Math.min(this.originalMaxConcurrent, this.maxConcurrent + 1);
                this.consecutiveLowAbort = 0;
            }
        }
        else {
            this.consecutiveLowAbort = 0;
        }
        return effective;
    }
    pump() {
        while (this.taskQueue.activeCount < this.maxConcurrent &&
            this.taskQueue.activeCount < this.maxDecodeTasks &&
            this.uploadsThisFrame < this.maxGpuUploads &&
            this.taskQueue.queue.length > 0) {
            const task = this.taskQueue.dequeue();
            if (task) {
                this.taskQueue.unmarkQueued(taskKey(task.frameId, task.x, task.y, task.z));
                this.uploadsThisFrame += 1;
                this.executeTask(task);
            }
        }
    }
    async executeTask(task) {
        const { frameId: id, frameUrl: url, x, y, z } = task;
        const key = taskKey(id, x, y, z);
        const controller = new AbortController();
        this.taskQueue.start(key, controller, task.frameId);
        this.totalTasks += 1;
        const t0 = performance.now();
        try {
            const registry = this.sharedRegistry ?? this.internalRegistry;
            const getTileData = this.getTileData;
            if (!getTileData || !this.device) {
                return;
            }
            const result = await registry.decodeTile({ id, url, x, y, z, getTileData }, {
                device: this.device,
                signal: (this.layerSignal && controller.signal
                    ? AbortSignal.any([this.layerSignal, controller.signal])
                    : (this.layerSignal ?? controller.signal)),
                pool: this.pool,
                requestInit: task.requestInit,
            });
            if (!result) {
                this.missingTileKeys.add(key);
                return;
            }
            const elapsed = performance.now() - t0;
            if (result.texture) {
                this.tileCache.put(id, x, y, z, {
                    x, y, z,
                    texture: result.texture,
                    mask: result.mask,
                    byteLength: result.byteLength ?? 0,
                    width: result.width,
                    height: result.height,
                    quality: "full",
                    origin: "prefetch",
                });
                if (elapsed > 0 && result.byteLength) {
                    this.recordTelemetry(elapsed, result.byteLength, id);
                }
            }
        }
        catch (err) {
            if (err?.name === "AbortError" || err?.cause?.name === "AbortError") {
                this.abortedTasks += 1;
            }
            else if (!isMissingTileError(err)) {
                console.warn("FramePrefetcher: tile fetch failed", err);
            }
        }
        finally {
            if (this.uploadsThisFrame > 0) {
                this.uploadsThisFrame -= 1;
            }
            this.taskQueue.finish(key);
            this.pump();
        }
    }
    recordTelemetry(sampleMs, sampleBytes, frameId) {
        const alpha = 0.125;
        if (this.rttEWMA === 0) {
            this.rttEWMA = sampleMs;
        }
        else {
            this.rttEWMA = alpha * sampleMs + (1 - alpha) * this.rttEWMA;
        }
        const throughput = sampleBytes / (sampleMs / 1000);
        if (this.throughputEWMA === 0) {
            this.throughputEWMA = throughput;
        }
        else {
            this.throughputEWMA = alpha * throughput + (1 - alpha) * this.throughputEWMA;
        }
        if (frameId && sampleBytes > 0) {
            const prev = this.frameAvgBytes.get(frameId);
            this.frameAvgBytes.set(frameId, prev ? alpha * sampleBytes + (1 - alpha) * prev : sampleBytes);
        }
    }
}
